sys.path.insert(0,'/home/claude/lengua')
import svgs as S
from svgs import svg, sun, cloud, tree, text, SKY, BLUE, ORANGE, GREEN, DGREEN, BROWN, DBROWN, YEL, GREY, DGREY, WHITE, RED, SAND, WATER, INK, PINK
S.OUT='/home/claude/subjects/cs/img'; os.makedirs(S.OUT,exist_ok=True)
PURPLE='#7D3C98'; SKIN='#F5CBA7'; LBLUE='#AED6F1'; GOLD='#D4AC0D'; LGREY='#D5D8DC'; GRASS='#7DCE82'; LGREEN='#A9DFBF'
def box(x,y,w,h,c,t='',sz=16,tc=WHITE,r=8): return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{c}"/>'+(text(x+w/2,y+h/2+sz*0.36,t,sz,tc) if t else '')
def person(x,y,s=1,shirt=BLUE): return f'<g transform="translate({x} {y}) scale({s})"><circle cx="0" cy="-30" r="14" fill="{SKIN}"/><circle cx="-5" cy="-33" r="2" fill="#000"/><circle cx="5" cy="-33" r="2" fill="#000"/><path d="M-6 -24 q6 6 12 0" stroke="#000" stroke-width="2" fill="none"/><rect x="-13" y="-15" width="26" height="34" rx="8" fill="{shirt}"/><rect x="-11" y="19" width="9" height="24" fill="{DGREY}"/><rect x="2" y="19" width="9" height="24" fill="{DGREY}"/></g>'
def house(x,y,s=1,c=SAND,roof=RED): return f'<g transform="translate({x} {y}) scale({s})"><rect x="-30" y="-30" width="60" height="50" fill="{c}"/><polygon points="-36,-30 0,-60 36,-30" fill="{roof}"/><rect x="-8" y="-4" width="16" height="24" fill="{DBROWN}"/><rect x="12" y="-20" width="12" height="12" fill="{WATER}"/></g>'
def building(x,y,w,h,c=GREY,win=LBLUE): return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" fill="{c}"/>'+''.join(f'<rect x="{x+6+i*14}" y="{y+8+j*16}" width="8" height="10" fill="{win}"/>' for i in range(int((w-6)//14)) for j in range(int((h-8)//16)))
def mountain(x,y,w,h,c=GREY,snow=True): return f'<polygon points="{x-w/2},{y} {x},{y-h} {x+w/2},{y}" fill="{c}"/>'+(f'<polygon points="{x-w/6},{y-h*0.67} {x},{y-h} {x+w/6},{y-h*0.67}" fill="{WHITE}"/>' if snow else '')
def arrow(x1,y1,x2,y2,c=INK,w=3,i='a'): return f'<defs><marker id="ah{i}" markerWidth="8" markerHeight="8" refX="6" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8 Z" fill="{c}"/></marker></defs><line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="{c}" stroke-width="{w}" marker-end="url(#ah{i})"/>'
def sign(x,y,kind,s=1):
    if kind=='stop': return f'<g transform="translate({x} {y}) scale({s})"><polygon points="-14,-30 14,-30 30,-14 30,14 14,30 -14,30 -30,14 -30,-14" fill="{RED}" stroke="{WHITE}" stroke-width="3"/>{text(0,6,"STOP",14,WHITE)}<rect x="-3" y="30" width="6" height="40" fill="{DGREY}"/></g>'
    if kind=='warn': return f'<g transform="translate({x} {y}) scale({s})"><polygon points="0,-32 32,26 -32,26" fill="{WHITE}" stroke="{RED}" stroke-width="6"/>{text(0,20,"!",26,INK)}<rect x="-3" y="28" width="6" height="42" fill="{DGREY}"/></g>'
    if kind=='must': return f'<g transform="translate({x} {y}) scale({s})"><circle cx="0" cy="0" r="30" fill="{BLUE}" stroke="{WHITE}" stroke-width="3"/>{arrow(0,16,0,-16,WHITE,5,"m")}<rect x="-3" y="30" width="6" height="40" fill="{DGREY}"/></g>'
    return f'<g transform="translate({x} {y}) scale({s})"><rect x="-30" y="-30" width="60" height="60" rx="6" fill="{BLUE}"/>{text(0,10,"P",30,WHITE)}<rect x="-3" y="30" width="6" height="40" fill="{DGREY}"/></g>'
def globe(x,y,r): return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{WATER}"/><path d="M{x-r*0.6} {y-r*0.4} q{r*0.3} -{r*0.4} {r*0.6} -{r*0.1} q{r*0.2} {r*0.3} -{r*0.1} {r*0.5} q-{r*0.4} {r*0.1} -{r*0.5} -{r*0.4}Z" fill="{GREEN}"/><path d="M{x+r*0.1} {y+r*0.2} q{r*0.4} -{r*0.2} {r*0.5} {r*0.2} q-{r*0.1} {r*0.4} -{r*0.4} {r*0.3}Z" fill="{GREEN}"/><ellipse cx="{x}" cy="{y}" rx="{r}" ry="{r*0.35}" fill="none" stroke="{WHITE}" stroke-width="2" stroke-dasharray="4 3"/>'
